namespace EgyptLab.LIS.Infrastructure.Domain;

/// <summary>
/// Base columns required on every table: UUID key, branch scope, timestamps,
/// and soft delete. Sync creates records independently at branches, so the
/// key is generated by the client rather than the database.
/// </summary>
public abstract class AuditedEntity
{
    public Guid Id { get; set; } = Guid.NewGuid();

    public Guid BranchId { get; set; }

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;

    public DateTimeOffset UpdatedAt { get; set; } = DateTimeOffset.UtcNow;

    public DateTimeOffset? DeletedAt { get; set; }
}
